const $=s=>document.querySelector(s), app=$('#app');
let role='customer',lang='en',data,view='home',selected=null,service='ac',step=1,busy=false;
let draft;try{draft=JSON.parse(localStorage.getItem('gramin-draft')||'{}');}catch{draft={};}
const t=(en,te)=>lang==='te'?te:en;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN');
const labels={requested:'Awaiting assignment',assigned:'Technician assigned',en_route:'On the way',inspecting:'Inspecting the issue',awaiting_approval:'Estimate needs approval',approved:'Estimate approved',repairing:'Repair in progress',completed:'Service completed',declined:'Repair declined',cancelled:'Cancelled'};
const telabels={requested:'కేటాయింపు కోసం వేచి ఉంది',assigned:'టెక్నీషియన్ కేటాయించారు',en_route:'దారిలో ఉన్నారు',inspecting:'సమస్య పరిశీలన',awaiting_approval:'అంచనా ఆమోదం కావాలి',approved:'అంచనా ఆమోదించారు',repairing:'రిపేర్ జరుగుతోంది',completed:'సేవ పూర్తయింది',declined:'రిపేర్ వద్దన్నారు',cancelled:'రద్దయింది'};
const status=b=>t(labels[b.status],telabels[b.status]);
const serviceIcon=id=>({ac:'<svg viewBox="0 0 24 24"><path d="M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M8 4l4 4 4-4M8 20l4-4 4 4"/></svg>',plumbing:'<svg viewBox="0 0 24 24"><path d="M12 3C9 8 5 11 5 15a7 7 0 0 0 14 0c0-4-4-7-7-12Z"/></svg>',electrical:'<svg viewBox="0 0 24 24"><path d="m14 2-9 12h7l-2 8 9-12h-7Z"/></svg>',washing:'<svg viewBox="0 0 24 24"><rect x="4" y="2" width="16" height="20" rx="2"/><path d="M4 7h16M7 4.5h2"/><circle cx="12" cy="14" r="4"/></svg>'}[id]);
const svc=id=>data.services.find(s=>s.id===id);
const token=()=>role==='customer'?'demo-customer':role==='admin'?'demo-admin':$('#technician')?.value||sessionStorage.getItem('gramin-tech')||'demo-tech-1';
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function load(){const r=await fetch('/api/state',{headers:{Authorization:'Bearer '+token()}});if(!r.ok)throw Error('Could not load the local demo');data=await r.json();}
async function act(action,input){if(busy)return;busy=true;document.querySelectorAll('button[type=submit],button[data-action]').forEach(b=>b.disabled=true);const signature=JSON.stringify({action,input,token:token()});let pending;try{pending=JSON.parse(sessionStorage.getItem('gramin-pending')||'null');}catch{}const key=pending?.signature===signature?pending.key:crypto.randomUUID();sessionStorage.setItem('gramin-pending',JSON.stringify({signature,key}));try{const r=await fetch('/api/actions',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token(),'Idempotency-Key':key},body:JSON.stringify({action,input})});const out=await r.json();if(!r.ok){sessionStorage.removeItem('gramin-pending');throw Error(out.error);}sessionStorage.removeItem('gramin-pending');selected=out.id||selected;if(action==='create'){view='booking';draft={};localStorage.removeItem('gramin-draft');}await load();render();toast(t('Saved to the local demo','నమూనాలో సేవ్ అయింది'));return out;}catch(e){toast(e.message==='Failed to fetch'?t('Connection lost. Your draft is saved. Reconnect and retry.','కనెక్షన్ లేదు. మళ్లీ ప్రయత్నించండి.'):e.message);}finally{busy=false;render();}}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function title(eyebrow,heading,sub=''){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1>${sub?`<p>${sub}</p>`:''}</div><span class="pill">${t('Narsipatnam area','నర్సీపట్నం ప్రాంతం')}</span></div>`;}
function render(){if(!data)return;document.documentElement.lang=lang;$('#language').textContent=lang==='en'?'తెలుగు':'English';$('.brand>span:last-child').innerHTML=`${esc(data.settings.brand)}<small>HOME SERVICES · SAMPLE BRAND</small>`;$('.location').innerHTML=t('Narsipatnam & nearby villages<small>Coverage confirmed by owner</small>','నర్సీపట్నం పరిసరాల్లో<small>సేవా ప్రాంతం నిర్ధారణ అవసరం</small>');$('.demo span:last-child').textContent='Sample brand, areas & fees · Local API · No real payments';$('footer span:nth-child(2)').textContent='Local demo · Drafts in browser, bookings on this computer';$('#roles').innerHTML=[['customer',t('Customer','కస్టమర్')],['technician',t('Technician','టెక్నీషియన్')],['admin',t('Owner / Admin','యజమాని')]].map(([id,label])=>`<button data-role="${id}" class="${role===id?'active':''}" aria-pressed="${role===id}">${label}</button>`).join('');app.innerHTML=role==='customer'?(view==='form'?bookingForm():view==='booking'?bookingView():home()):role==='admin'?adminView():technicianView();bind();}
function home(){return title('YOUR NEIGHBOURHOOD SERVICE DESK',t('A little help. Right at home.','మీ ఇంటి పనులకు, మా సహాయం.'),t('Choose a service. We’ll help with the next step.','సేవను ఎంచుకోండి. మిగతాది మేము చూసుకుంటాం.'))+`<div class="layout"><section><div class="services">${data.services.map(s=>`<button class="service" data-service="${s.id}"><span class="icon" aria-hidden="true">${serviceIcon(s.id)}</span><strong>${t(s.en,s.te)}</strong><small>${t(s.detail,s.en)}</small></button>`).join('')}</div><div class="note">${t('Know the cost before the repair. A technician inspects the issue and sends an estimate for your approval.','రిపేర్ ముందు ఖర్చు తెలుసుకోండి. మీ ఆమోదం తర్వాతే పని మొదలవుతుంది.')}</div><div class="card"><div class="row"><h3>${t('Your service requests','మీ సేవా అభ్యర్థనలు')}</h3><span class="pill">${data.bookings.length}</span></div>${data.bookings.length?data.bookings.map(b=>jobRow(b)).join(''):`<p class="muted">${t('Your first booking will appear here.','మీ మొదటి బుకింగ్ ఇక్కడ కనిపిస్తుంది.')}</p>`}</div></section><aside><div class="card dark"><div class="eyebrow">FROM YOUR REQUEST TO YOUR REPAIR</div><h2>${t('Someone to take care of it.','మీ పనికి మా తోడు.')}</h2><div class="steps"><div class="step"><span class="number">01</span><div><strong>${t('Tell us what needs fixing','సమస్యను చెప్పండి')}</strong><small>${t('Share your village, landmark and a convenient visit window.','మీ గ్రామం, గుర్తు, సమయం తెలపండి.')}</small></div></div><div class="step"><span class="number">02</span><div><strong>${t('We find the right technician','టెక్నీషియన్‌ను కేటాయిస్తాం')}</strong><small>${t('The owner checks coverage and assigns your visit.','యజమాని ప్రాంతాన్ని నిర్ధారించి కేటాయిస్తారు.')}</small></div></div><div class="step"><span class="number">03</span><div><strong>${t('Approve, repair, then pay','ఆమోదం, రిపేర్, చెల్లింపు')}</strong><small>${t('Review the itemised cost. Pay after the visit is completed.','ఖర్చు పరిశీలించి, పని పూర్తయ్యాక చెల్లించండి.')}</small></div></div></div></div><div class="card"><h3>${t('Your village matters','మీ గ్రామమే ముఖ్యం')}</h3><p class="muted">${t('A house number is optional. A nearby school, temple or shop helps us find you.','ఇంటి నంబర్ లేకపోయినా, దగ్గరలోని పాఠశాల లేదా దుకాణం గుర్తు చెప్పండి.')}</p><span class="pill">${t('Drafts saved on this device','వివరాలు ఈ పరికరంలో సేవ్ అవుతాయి')}</span></div></aside></div>`;}
function jobRow(b){return `<div class="job ${selected===b.id?'selected':''}"><div class="row"><strong>${t(svc(b.service).en,svc(b.service).te)}</strong><span class="pill">${status(b)}</span></div><p>${esc(b.id)} · ${esc(b.village)}</p><div class="row"><small>${esc(b.slot)}</small><button class="quiet" data-open="${b.id}">${t('View request','వివరాలు చూడండి')} →</button></div></div>`;}
function bookingForm(){const s=svc(service);return `<button class="back" id="back">← ${t('All services','అన్ని సేవలు')}</button>`+title('NEW SERVICE REQUEST',t(s.en,s.te),t('A few details help us plan your visit.','కొన్ని వివరాలు తెలపండి.'))+`<div class="layout"><section class="card"><div class="progress-bar"><span class="on"></span><span class="${step>=2?'on':''}"></span></div><h2>${step===1?t('1. Your home & the issue','1. మీ చిరునామా, సమస్య'):t('2. Visit window & review','2. సమయం, వివరాల పరిశీలన')}</h2><form id="booking-form">${step===1?`<div class="fields">${field(t('Your name','మీ పేరు'),'name',draft.name,'text','required maxlength="80" autocomplete="name"')}${field(t('Mobile number','మొబైల్ నంబర్'),'phone',draft.phone,'tel','required pattern="[6-9][0-9]{9}" maxlength="10" inputmode="numeric" autocomplete="tel"')}${field(t('Village / neighbourhood','గ్రామం / ప్రాంతం'),'village',draft.village,'text','required maxlength="100" list="areas"')}${field('PIN code','pin',draft.pin,'text','required pattern="[0-9]{6}" maxlength="6" inputmode="numeric"')}</div><datalist id="areas">${data.settings.areas.map(a=>`<option value="${esc(a)}"></option>`).join('')}</datalist>${field(t('Landmark & directions','దగ్గరలో గుర్తు, దారి వివరాలు'),'landmark',draft.landmark,'text','required maxlength="250" placeholder="e.g. Beside the school, blue gate"')}<label class="field">${t('What is the problem?','సమస్య ఏమిటి?')}<textarea name="issue" required maxlength="500" placeholder="e.g. AC turns on but does not cool">${esc(draft.issue)}</textarea></label><button class="primary full" type="submit">${t('Continue to visit details','సమయం ఎంచుకోండి')} →</button>`:`<label class="field">${t('Preferred visit window','అనుకూల సమయం')}<select name="slot" required>${['Today · 9 am – 1 pm','Today · 2 pm – 6 pm','Tomorrow · 9 am – 1 pm','Tomorrow · 2 pm – 6 pm'].map(s=>`<option ${draft.slot===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="note">${t('Requested window only. The owner will confirm availability and village coverage.','యజమాని సమయం, సేవా ప్రాంతాన్ని నిర్ధారిస్తారు.')}</div><h3>${esc(draft.name)} · ${esc(draft.phone)}</h3><p>${esc(draft.village)} · ${esc(draft.pin)}<br>${esc(draft.landmark)}</p><p class="muted">${esc(draft.issue)}</p><label class="check"><input type="checkbox" name="consent" required>${t('I accept the sample visit + travel charges shown, including if I decline the repair. This creates a demo request only.','రిపేర్ వద్దన్నా, చూపిన నమూనా సందర్శన, ప్రయాణ ఛార్జీలకు అంగీకరిస్తున్నాను. ఇది నమూనా అభ్యర్థన మాత్రమే.')}</label><div class="row"><button class="secondary" type="button" id="edit-details">${t('Edit details','వివరాలు మార్చండి')}</button><button class="primary" type="submit">${t('Send demo request','నమూనా అభ్యర్థన పంపండి')}</button></div>`}</form></section><aside><div class="card"><span class="pill">SAMPLE FEES · EDITABLE BY OWNER</span><h2 style="margin-top:20px">${t('Clear from the start','ముందే స్పష్టమైన ఖర్చు')}</h2><div class="line"><span>${t('Inspection / visit','సందర్శన')}</span><strong>${money(data.settings.visitFee)}</strong></div><div class="line"><span>${t('Sample travel charge','నమూనా ప్రయాణ ఛార్జీ')}</span><strong>${money(data.settings.travelFee)}</strong></div><div class="divider"></div><div class="line"><strong>${t('Visit total','సందర్శన మొత్తం')}</strong><strong>${money(data.settings.visitFee+data.settings.travelFee)}</strong></div><p class="muted">${t('Labour and parts are quoted after inspection. Nothing is repaired until you approve.','పరిశీలన తర్వాత పని, విడిభాగాల అంచనా ఇస్తారు.')}</p><div class="note warn">${t('Prices and coverage are examples, not a business offer. No payment is collected.','ధరలు, ప్రాంతాలు నమూనా మాత్రమే. చెల్లింపు తీసుకోబడదు.')}</div></div><div class="note">PIN check: Narsipatnam 531116; Makavarapalem 531113. Enter your own village PIN.</div></aside></div>`;}
function summary(b){return `<div class="card"><div class="row"><span class="eyebrow">${esc(b.id)}</span><span class="pill">${status(b)}</span></div><h2 style="margin-top:18px">${t(svc(b.service).en,svc(b.service).te)}</h2><p>${esc(b.issue)}</p><div class="divider"></div><h3>${esc(b.name)}</h3><p>${esc(b.village)} · ${esc(b.pin)}<br>${esc(b.landmark)}</p><div class="line"><span>${t('Preferred visit','అనుకూల సమయం')}</span><strong>${esc(b.slot)}</strong></div>${role!=='customer'?`<div class="line"><span>Mobile</span><strong>${esc(b.phone)}</strong></div>`:''}<div class="note">${t('Coverage and timing require owner confirmation.','సేవా ప్రాంతం, సమయం యజమాని నిర్ధారించాలి.')}</div></div>`;}
function estimate(b){return `<h3>${t('Repair estimate','రిపేర్ అంచనా')}</h3><p>${esc(b.estimate.description)}</p>${[['Inspection / visit',b.fees.visit],['Travel',b.fees.travel],['Labour',b.estimate.labor],['Parts',b.estimate.parts]].map(([l,v])=>`<div class="line"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="divider"></div><div class="line"><strong>${t('Total · sample','మొత్తం · నమూనా')}</strong><strong>${money(b.estimate.total)}</strong></div>`;}
function actionButton(action,label,input={},kind='primary'){return `<button class="${kind}" data-action="${action}" data-input="${esc(JSON.stringify(input))}">${label}</button>`;}
function payment(b){if(b.paymentStatus==='paid')return `<div class="receipt"><span class="pill">DEMO PAYMENT COMPLETE</span><div class="price">${money(b.amountDue)}</div><p>Receipt ${esc(b.receipt)}<br>No money was transferred.</p></div>`;return `<h3>${t('Payment after service','సేవ తర్వాత చెల్లింపు')}</h3><div class="price">${money(b.amountDue)}</div>${b.paymentStatus==='cash_pending'?`<div class="note">Cash selected. Waiting for the technician to confirm collection in the demo.</div>`:`<p class="muted">${t('Choose a simulated payment. No UPI app or bank will be opened.','నమూనా చెల్లింపు ఎంచుకోండి. బ్యాంకు లావాదేవీ జరగదు.')}</p>${b.paymentStatus==='failed'?'<div class="note warn">Demo payment failed. You can retry safely.</div>':''}<div class="row wrap">${actionButton('pay','Simulate UPI success',{method:'demo_upi'})}${actionButton('pay','Pay cash',{method:'cash'},'secondary')}${actionButton('pay','Test failed payment',{method:'demo_upi',outcome:'failed'},'quiet')}</div>`}`;}
function bookingView(){const b=data.bookings.find(b=>b.id===selected);if(!b){view='home';return home();}const stages=['requested','assigned','en_route','inspecting','awaiting_approval','approved','repairing','completed'];const idx=stages.indexOf(b.status);const tech=data.technicians.find(x=>x.id===b.technicianId);return `<button class="back" id="back">← ${t('Your services','మీ సేవలు')}</button>`+title('YOUR SERVICE REQUEST',status(b),t('Follow your visit, one step at a time.','మీ సేవ స్థితిని చూడండి.'))+`<div class="layout"><section>${summary(b)}${b.estimate?`<div class="card">${estimate(b)}${b.status==='awaiting_approval'?`<div class="note">Declining the repair leaves only the agreed visit and travel fee of ${money(b.fees.visit+b.fees.travel)}.</div><div class="row">${actionButton('approve',t('Approve estimate','అంచనా ఆమోదించండి'))}${actionButton('decline',t('Decline repair','రిపేర్ వద్దు'),{},'danger')}</div>`:b.approvedAt?'<span class="pill">Approved by customer</span>':''}</div>`:''}${['completed','declined'].includes(b.status)?`<div class="card">${b.notes?`<h3>Completion notes</h3><p>${esc(b.notes)}</p>`:''}${payment(b)}${b.status==='completed'?`<div class="divider"></div><h3>${t('How was your service?','సేవ ఎలా ఉంది?')}</h3><div class="rating" aria-label="Service rating">${[1,2,3,4,5].map(n=>`<button aria-label="${n} stars" aria-pressed="${b.rating===n}" data-action="rate" data-input='{"rating":${n}}'>${n}★</button>`).join('')}</div>`:''}</div>`:''}</section><aside><div class="card dark"><div class="eyebrow">${t('YOUR TECHNICIAN','మీ టెక్నీషియన్')}</div><h2 style="margin-top:14px">${tech?esc(tech.name):t('We’re finding your technician','టెక్నీషియన్‌ను కేటాయించాలి')}</h2><p class="muted">${b.status==='en_route'?`Estimated arrival: ${b.eta} minutes · entered by technician. Demo, not live GPS.`:tech?'Sample technician · Assigned by the owner':'Switch to Owner / Admin to assign this demo request.'}</p><small>Last update: ${new Date(b.updatedAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}. Use Refresh for the latest state.</small><button id="refresh" class="secondary full" style="margin-top:16px">${t('Refresh status','స్థితి తాజాగా చూడండి')}</button></div><div class="card"><h3>${t('Visit progress','సేవ పురోగతి')}</h3>${['cancelled','declined'].includes(b.status)?`<p>${status(b)}</p>`:`<ol class="timeline">${stages.map((s,i)=>`<li class="${i<=idx?'done':''} ${i===idx?'current':''}">${t(labels[s],telabels[s])}</li>`).join('')}</ol>`}${['requested','assigned'].includes(b.status)?actionButton('cancel',t('Cancel request','రద్దు చేయండి'),{},'danger'):''}</div></aside></div>`;}
function adminView(){const b=data.bookings.find(x=>x.id===selected);return title('OPERATIONS · OWNER WORKSPACE',t('Every village. Every visit.','ప్రతి గ్రామం. ప్రతి సేవ.'),'Assign requests, confirm costs and keep visits moving.')+`<div class="stats"><div class="stat">Awaiting assignment<b>${data.bookings.filter(b=>b.status==='requested').length}</b></div><div class="stat">Active visits<b>${data.bookings.filter(b=>!['requested','completed','cancelled','declined'].includes(b.status)).length}</b></div><div class="stat">Completed<b>${data.bookings.filter(b=>b.status==='completed').length}</b></div></div><div class="layout"><section><div class="card"><div class="row"><h2>Dispatch desk</h2><button class="quiet" id="refresh">Refresh</button></div>${data.bookings.length?data.bookings.map(jobRow).join(''):'<div class="empty"><span class="icon">⌂</span><h3>No requests yet</h3><p class="muted">Create a request in the Customer view to start the complete demo.</p></div>'}</div>${b?summary(b):''}</section><aside>${b?`<div class="card"><span class="eyebrow">${esc(b.id)} · DISPATCH</span><h2 style="margin-top:12px">${esc(b.name)}</h2>${['requested','assigned'].includes(b.status)?`<form id="assign-form"><label class="field">Available sample technicians<select name="technicianId">${data.technicians.filter(t=>t.skills.includes(b.service)).map(t=>`<option value="${t.id}">${t.name} · ${data.bookings.filter(x=>x.technicianId===t.id&&!['completed','declined','cancelled'].includes(x.status)).length} active</option>`).join('')}</select></label><label class="check"><input type="checkbox" required>I have checked coverage, travel fee and the visit window in this demo.</label><button class="primary full" type="submit">Assign technician</button></form>`:`<p>${status(b)}<br>${esc(data.technicians.find(t=>t.id===b.technicianId)?.name||'Unassigned')}</p>${b.estimate?estimate(b):''}<p>Payment: ${esc(b.paymentStatus)}</p>`}</div>`:''}<div class="card"><div class="eyebrow">EDITABLE SAMPLE SETTINGS</div><h2 style="margin-top:12px">Service area & fees</h2><form id="settings-form">${field('Working brand','brand',data.settings.brand,'text','required maxlength="40"')}<label class="field">Sample areas · one per line<textarea name="areas" required>${esc(data.settings.areas.join('\n'))}</textarea></label><div class="fields">${field('Visit fee · ₹','visitFee',data.settings.visitFee,'number','min="0" max="100000" required')}${field('Travel fee · ₹','travelFee',data.settings.travelFee,'number','min="0" max="100000" required')}</div>${field('Sample radius · km','radius',data.settings.radius,'number','min="0" max="100000" required')}<div class="note warn">Coverage is manually confirmed. Radius is a planning value, not a live distance check. New fees apply only to new requests.</div><button class="secondary full" type="submit">Save sample settings</button></form></div></aside></div>`;}
function technicianView(){const b=data.bookings.find(x=>x.id===selected)||data.bookings.find(x=>!['cancelled'].includes(x.status));if(b)selected=b.id;return title('FIELD WORK · TECHNICIAN WORKSPACE',t('Your next visit, made clear.','మీ తదుపరి సేవ వివరాలు.'),'Check directions, inspect the issue and wait for customer approval.')+`<label class="field">Demo technician<select id="technician">${data.technicians.map(t=>`<option value="demo-${t.id}" ${token()==='demo-'+t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><div class="layout"><section><div class="card"><div class="row"><h2>Assigned visits</h2><button class="quiet" id="refresh">Refresh</button></div>${data.bookings.length?data.bookings.map(jobRow).join(''):'<div class="empty"><h3>No assigned visits</h3><p class="muted">The owner must assign a matching service to this technician.</p></div>'}</div>${b?summary(b):''}</section><aside>${b?`<div class="card"><span class="pill">${status(b)}</span><h2 style="margin-top:20px">Visit actions</h2>${b.status==='assigned'?`<form id="depart-form">${field('Estimated arrival · minutes (demo)','eta',30,'number','min="5" max="240" required')}<button class="primary full" type="submit">Start journey</button></form>`:b.status==='en_route'?`<p>Demo ETA: ${b.eta} minutes. This is manually entered, not GPS.</p>${actionButton('arrive','I have arrived')}`:b.status==='inspecting'?`<form id="estimate-form"><label class="field">Inspection & proposed repair<textarea name="description" required maxlength="500" placeholder="Describe the problem and work needed"></textarea></label>${field('Labour · ₹','labor',350,'number','min="0" max="100000" required')}${field('Parts · ₹','parts',200,'number','min="0" max="100000" required')}<p class="muted">Visit + travel: ${money(b.fees.visit+b.fees.travel)}. These are included in the total.</p><button class="primary full" type="submit">Send estimate for approval</button></form>`:b.status==='awaiting_approval'?'<div class="note warn">Wait for the customer to approve. Repair actions are locked until approval.</div>':b.status==='approved'?actionButton('start','Start approved repair'):b.status==='repairing'?`<form id="complete-form"><label class="field">Completion notes<textarea name="notes" required maxlength="1000" placeholder="What was repaired and checked?"></textarea></label><label class="check"><input type="checkbox" required>I have checked the repair with the customer.</label><button class="primary full" type="submit">Mark service complete</button></form>`:`<p>${status(b)}</p><p>Payment: ${esc(b.paymentStatus)}</p>${b.paymentStatus==='cash_pending'?actionButton('cash_received','Confirm demo cash received'):''}`}${b.estimate?`<div class="divider"></div>${estimate(b)}`:''}</div>`:''}<div class="card dark"><h3>Before you begin</h3><p class="muted">Confirm the landmark. Explain the issue and quote all costs. Start repair only after customer approval.</p><small>Offline? Keep the page open. Status changes need a connection to the local server; retry after reconnecting.</small></div></aside></div>`;}
function bind(){document.querySelectorAll('[data-role]').forEach(b=>b.onclick=async()=>{role=b.dataset.role;view='home';selected=null;try{await load();render();}catch(e){toast(e.message);}});document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{service=b.dataset.service;view='form';step=1;render();});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.open;if(role==='customer')view='booking';render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,{id:selected,...JSON.parse(b.dataset.input)}));if($('#back'))$('#back').onclick=()=>{view='home';render();};if($('#edit-details'))$('#edit-details').onclick=()=>{step=1;render();};if($('#refresh'))$('#refresh').onclick=async()=>{try{await load();render();toast('Status refreshed');}catch(e){toast(e.message);}};if($('#technician'))$('#technician').onchange=async e=>{sessionStorage.setItem('gramin-tech',e.target.value);selected=null;await load();render();};const f=$('#booking-form');if(f){f.oninput=()=>{Object.assign(draft,Object.fromEntries(new FormData(f)));try{localStorage.setItem('gramin-draft',JSON.stringify(draft));}catch{toast('Draft could not be saved on this device');}};f.onsubmit=e=>{e.preventDefault();Object.assign(draft,Object.fromEntries(new FormData(f)));if(step===1){step=2;render();}else act('create',{...draft,service,consent:true});};}const forms={'assign-form':['assign',o=>o],'depart-form':['depart',o=>({eta:Number(o.eta)})],'estimate-form':['estimate',o=>({...o,labor:Number(o.labor),parts:Number(o.parts)})],'complete-form':['complete',o=>o],'settings-form':['settings',o=>({...o,areas:o.areas.split('\n').map(x=>x.trim()).filter(Boolean),visitFee:Number(o.visitFee),travelFee:Number(o.travelFee),radius:Number(o.radius)})]};for(const[id,[action,map]]of Object.entries(forms)){const form=$('#'+id);if(form)form.onsubmit=e=>{e.preventDefault();act(action,{...(action==='settings'?{}:{id:selected}),...map(Object.fromEntries(new FormData(form)))});};}}
$('#language').onclick=()=>{lang=lang==='en'?'te':'en';render();};$('#reset').textContent='Clear saved draft';$('#reset').onclick=()=>{localStorage.removeItem('gramin-draft');draft={};toast('Saved draft cleared. Existing bookings are retained.');};
window.addEventListener('offline',()=>toast('Offline. Booking drafts stay on this device. Reconnect before submitting.'));
load().then(render).catch(()=>{app.innerHTML='<div class="card"><h1>Local server unavailable</h1><p>Start the app with npm start, then open http://127.0.0.1:4173.</p><button onclick="location.reload()" class="primary">Try again</button></div>';});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_visible_bookings',description:'Read bookings available to the active demo role. Does not modify data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{await load();render();return {role,bookings:data.bookings.map(b=>({id:b.id,status:b.status,paymentStatus:b.paymentStatus}))};}})).catch(()=>{});}catch{}}
